# Maybe count connected components of 5s?
def count_neighbors(grid, r, c, val):
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    count = 0
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == val:
                count += 1
    return count

# Check 5 at each position
out = []
for r in range(len(grid)):
    row_out = []
    for c in range(len(grid[0])):
        if grid[r][c] == 5:
            n = count_neighbors(grid, r, c, 5)
            row_out.append(n)
        else:
            row_out.append(-1)
    out.append(row_out)

print("Neighbor counts for 5s:")
for row in out:
    print(row)

